/* Local automatic import: review a workbook summary, then resolve exceptions. */
(function(){'use strict';const E=window.ExcelCourse;let workbook=null,candidates=[],report=null,epoch=0;
const dialog=document.createElement('dialog');dialog.id='excel-dialog';dialog.className='modal excel-modal';dialog.setAttribute('aria-labelledby','excel-title');dialog.innerHTML=`<div class="panel-head"><h2 id="excel-title">课表导入预览</h2><button class="close" id="excel-close" aria-label="取消 Excel 导入">×</button></div><p id="excel-status" role="status">只在本机读取课表。</p><div id="excel-review" hidden><div id="excel-summary" class="excel-raw"></div><p id="excel-view-conflicts" class="excel-warning" hidden></p><div id="excel-sheets"></div><div id="excel-term" hidden><p class="fine">以下课程只有星期／周次。请补充学期信息，文件中已有具体日期的课程保持原日期。</p><div class="field-row"><label class="field"><span>第 1 周星期一</span><input id="excel-monday" type="date"></label><label class="field"><span>学期周数 · 缺周次时必填</span><input id="excel-weeks" type="number" min="1" max="30" placeholder="不推断"></label></div></div><div id="excel-problems"></div><label id="excel-ack-label" class="switch" hidden><input id="excel-ack" type="checkbox">已核对附加文字；缺钟点的课程保留无时间</label><details id="excel-advanced"><summary>高级编辑 · 工作表与字段映射</summary><div id="excel-config"><label class="field"><span>工作表</span><select id="excel-sheet"></select></label><div class="field-row"><label class="field"><span>布局</span><select id="excel-layout"><option value="list">日期列表</option><option value="grid">横向星期网格</option></select></label><label class="field"><span>标题行</span><input id="excel-header" type="number" min="1" max="30" value="1"></label></div><div id="excel-list-map"></div><div id="excel-grid-map" hidden><label class="field"><span>节次／钟点列</span><select id="excel-period"></select></label></div><button id="excel-analyze" class="secondary dialog-close">应用所选页的映射</button></div><p class="fine">只替换所选页的识别结果，其他已纳入页保留。纵向网格由自动识别处理；无法识别的布局可整理为日期列表。</p><div id="excel-candidates"></div></details><button id="excel-stage" class="primary dialog-close">确认汇总 · 继续</button></div><p class="error" id="excel-error" role="alert" hidden></p><button class="secondary dialog-close" id="excel-cancel">取消导入</button>`;document.body.append(dialog);
const style=document.createElement('style');style.textContent='.excel-modal{max-width:460px;max-height:calc(var(--vh) - 32px);overflow:auto}.excel-modal .field-row{grid-template-columns:1fr 1fr}.excel-entry{padding:12px;background:#fff;border:1px solid var(--line);border-radius:16px;margin-top:10px}.excel-entry summary,#excel-advanced>summary{font-size:14px;min-height:44px;cursor:pointer;display:flex;align-items:center;overflow-wrap:anywhere}.excel-raw{white-space:pre-wrap;overflow-wrap:anywhere;padding:12px;background:#f4f5f3;font-size:12px;line-height:1.65;border-radius:10px}.excel-warning{color:#85665b;font-size:12px;line-height:1.7}.excel-modal .switch{line-height:1.7}.excel-modal input[type=checkbox]{width:20px;height:20px}.excel-sheet-line{padding:8px 0;font-size:12px;line-height:1.7}';document.head.append(style);
const fields=[['date','日期'],['name','课程名称'],['location','地点／教室'],['start','开始时间'],['end','结束时间']];
function fail(message){$('excel-error').textContent=message;$('excel-error').hidden=false;}
function cancel(){epoch++;workbook=null;candidates=[];report=null;dialog.close();$('add').focus();}
$('excel-close').onclick=$('excel-cancel').onclick=cancel;dialog.addEventListener('cancel',cancel);
function sheet(){return workbook?.worksheets.find(s=>String(s.id)===$('excel-sheet').value);}
function options(s,row){let a='<option value="0">未映射</option>';for(let col=1;col<=Math.min(s.columnCount,40);col++)a+='<option value="'+col+'">第 '+col+' 列 · '+escapeHTML(E.cellText(s.getCell(row,col)).slice(0,30))+'</option>';return a;}
function mapping(){const s=sheet();if(!s)return;const r=+$('excel-header').value,opts=options(s,r),map=E.autoMap(s,r);$('excel-list-map').innerHTML=fields.map(([k,label])=>'<label class="field"><span>'+label+'</span><select id="excel-map-'+k+'">'+opts+'</select></label>').join('');for(const[k]of fields)$('excel-map-'+k).value=String(map[k]);$('excel-period').innerHTML=opts;$('excel-period').value='1';layout();}
function layout(){const grid=$('excel-layout').value==='grid';$('excel-list-map').hidden=grid;$('excel-grid-map').hidden=!grid;}
$('excel-sheet').onchange=()=>{const s=sheet();if(!s)return;const d=E.detect(s);$('excel-layout').value=d.grid?'grid':'list';$('excel-header').value=d.grid||d.list;mapping();};$('excel-header').oninput=mapping;$('excel-layout').onchange=layout;
function field(i,k,label,type='text',value=''){return '<label class="field"><span>'+label+'</span><input data-candidate="'+i+'" data-key="'+k+'" type="'+type+'" value="'+escapeHTML(value)+'"'+(k==='name'?' maxlength="120"':k==='location'?' maxlength="200"':'')+'></label>';}
function problematic(c){return !c.name||(!c.date&&(!c.day||!c.weeks))||!c.start||!c.end||c.warnings.length>0||c.conflicts?.length;}
function entry(c,i,open=false){return '<details class="excel-entry"'+(open?' open':'')+'><summary>'+escapeHTML(c.name||'待填写课程')+' · '+escapeHTML(c.date||('星期'+(c.day||'?')+' · '+(c.weeks||'待填周次')))+(c.start?' · '+escapeHTML(c.start)+'–'+escapeHTML(c.end):' · 无完整时间')+'</summary><label class="switch"><input type="checkbox" data-candidate="'+i+'" data-key="exclude"'+(c.exclude?' checked':'')+'>排除此课程</label><div class="excel-raw">'+escapeHTML(c.source)+'\n'+escapeHTML(c.raw.join('\n'))+'</div>'+(c.conflicts?.length?'<p class="excel-warning">时间重叠：'+escapeHTML(c.conflicts.join('、'))+'。请调整或排除冲突课程／重复视图。</p>':'')+(c.warnings.length?'<p class="excel-warning">'+c.warnings.map(escapeHTML).join('<br>')+'</p>':'')+field(i,'name','课程名称','text',c.name)+field(i,'location','地点 · 可留空','text',c.location)+field(i,'date','具体日期 · 填写后优先使用','date',c.date||'')+(!c.date?'<div class="field-row"><label class="field"><span>星期</span><select data-candidate="'+i+'" data-key="day"><option value="">待选择</option>'+[1,2,3,4,5,6,7].map(d=>'<option value="'+d+'"'+(+c.day===d?' selected':'')+'>星期'+['一','二','三','四','五','六','日'][d-1]+'</option>').join('')+'</select></label>'+field(i,'weeks','周次','text',c.weeks)+'</div>':'')+'<div class="field-row">'+field(i,'start','开始时间','time',c.start)+field(i,'end','结束时间','time',c.end)+'</div></details>';}
function selected(c){return !c.exclude&&!report.sheets.find(s=>s.name===c.sheet)?.excluded;}
function stats(){for(const c of candidates)c.conflicts=[];const viewConflicts=new Set();const kept=candidates.filter(selected),untimed=kept.filter(c=>!c.start||!c.end).length;$('excel-term').hidden=!kept.some(c=>!c.date&&(!c.anchorMonday||!c.weeks||/^[单双]周$/.test(c.weeks))); $('excel-ack-label').hidden=!kept.some(c=>!c.start||!c.end||c.warnings.length);let expanded='';try{let rows=[],unresolved=0;for(const c of kept){try{rows.push(...E.materialize([c],{monday:$('excel-monday').value,maxWeeks:+$('excel-weeks').value}));}catch{unresolved++;}}rows=rows.length?E.materialize(rows):[];const timed=rows.filter(c=>c.start&&c.end).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));for(let i=1;i<timed.length;i++){for(let j=i-1;j>=0&&timed[j].date===timed[i].date;j--){if(timed[j].end>timed[i].start){if(timed[j].sheet!==timed[i].sheet){viewConflicts.add(timed[j].sheet);viewConflicts.add(timed[i].sheet);}else for(const c of kept)if([timed[j].source,timed[i].source].includes(c.source)&&!c.conflicts.includes(timed[i].date))c.conflicts.push(timed[i].date);}}}expanded='\n展开后 '+rows.length+' 节课 · '+rows.reduce((a,c)=>a.add(c.date),new Set()).size+' 个上课日'+(unresolved?'（另有 '+unresolved+' 条待补充）':'');}catch{}$('excel-view-conflicts').hidden=!viewConflicts.size;$('excel-view-conflicts').textContent=viewConflicts.size?'部分工作表在相同日期存在不同课程表达或时间重叠，可能是重复视图。请在下方集中选择保留的页，或用高级编辑修改：'+[...viewConflicts].join('、'):'';$('excel-summary').textContent='已纳入 '+report.sheets.filter(s=>!s.excluded&&s.count).length+' 张课程页 · '+kept.length+' 条课程块'+expanded+'\n'+untimed+' 条缺完整时间 · '+kept.filter(c=>!c.location).length+' 条缺地点（可留空）\n每条来源可在高级编辑中查看。尚未替换原课表。';}
function render(){stats();const problems=candidates.map((c,i)=>({c,i})).filter(x=>selected(x.c)&&problematic(x.c));$('excel-problems').innerHTML=problems.length?'<p class="fine">集中校对 · '+problems.length+' 条需要补充或核对</p>'+problems.map(x=>entry(x.c,x.i)).join(''):'<p class="fine">关键字段完整，可直接确认汇总。</p>';$('excel-candidates').innerHTML=candidates.map((c,i)=>entry(c,i)).join('');$('excel-sheets').innerHTML=report.sheets.map((s,i)=>'<div class="excel-sheet-line">'+(s.count||s.status==='unresolved'?'<label><input type="checkbox" data-sheet="'+i+'"'+(!s.excluded?' checked':'')+'> ':'')+escapeHTML(s.name)+' · '+s.count+' 条 · '+escapeHTML(s.message)+(s.count||s.status==='unresolved'?'</label>':'')+'</div>').join('');for(const el of dialog.querySelectorAll('[data-sheet]'))el.onchange=()=>{report.sheets[+el.dataset.sheet].excluded=!el.checked;$('excel-ack').checked=false;render();};for(const el of dialog.querySelectorAll('[data-candidate]'))el.oninput=()=>{const i=+el.dataset.candidate,k=el.dataset.key,v=el.type==='checkbox'?el.checked:el.value;candidates[i][k]=v;for(const other of dialog.querySelectorAll('[data-candidate="'+i+'"][data-key="'+k+'"]'))if(other!==el){if(other.type==='checkbox')other.checked=v;else other.value=v;}$('excel-ack').checked=false;$('excel-error').hidden=true;stats();};stats();}
for(const id of['excel-monday','excel-weeks'])$(id).oninput=()=>{$('excel-ack').checked=false;render();};
$('excel-analyze').onclick=()=>{try{const s=sheet(),row=+$('excel-header').value;if(!s||!Number.isInteger(row)||row<1||row>Math.min(30,s.rowCount))throw Error('请选择工作表及有效标题行。');const fresh=$('excel-layout').value==='grid'?E.grid(s,row,+$('excel-period').value):E.list(s,row,Object.fromEntries(fields.map(([k])=>[k,+$('excel-map-'+k).value])));candidates=candidates.filter(c=>c.sheet!==s.name).concat(fresh.map(c=>({...c,sheet:s.name,sheetId:s.id,exclude:false})));const meta=report.sheets.find(x=>x.name===s.name);Object.assign(meta,{count:fresh.length,status:'included',excluded:false,message:'使用手动映射'});$('excel-ack').checked=false;$('excel-error').hidden=true;render();}catch(e){fail(e.message);}};
$('excel-stage').onclick=()=>{try{if(report.sheets.some(s=>s.status==='unresolved'&&!s.excluded))throw Error('仍有未识别工作表，请在汇总中明确取消纳入，或在高级编辑中映射。');const kept=candidates.filter(selected);if(!$('excel-ack-label').hidden&&!$('excel-ack').checked)throw Error('请集中核对提示，并确认缺钟点课程保留无时间。');if(kept.some(c=>c.blocked))throw Error('手动映射发现多课程歧义，请编辑源文件或排除该项。');const rows=E.materialize(kept,{monday:$('excel-monday').value,maxWeeks:+$('excel-weeks').value});const result=validateCourses(rows);dialog.close();stageImport(result,window.excelFilename+' · 汇总 '+report.sheets.filter(s=>s.count&&!s.excluded).length+' 张课程页 · '+result.length+' 节课');}catch(e){fail(e.message);$('excel-error').scrollIntoView({block:'center'});}};
window.openExcelImport=async file=>{const token=++epoch;workbook=null;report=null;candidates=[];$('excel-review').hidden=true;$('excel-error').hidden=true;$('excel-ack').checked=false;$('excel-advanced').open=false;$('excel-monday').value='';$('excel-weeks').value='';$('excel-status').textContent='正在本机自动识别 '+file.name+'…';window.excelFilename=file.name;dialog.showModal();try{if(file.size>5*1024*1024)throw Error('Excel 文件超过 5 MB，请拆分。');if(file.name.toLowerCase().endsWith('.xls'))throw Error('支持 XLSX；旧 XLS 请在 Excel / WPS 中另存为 XLSX。');const bytes=await file.arrayBuffer();E.preflight(bytes);if(token!==epoch)return;const w=new ExcelJS.Workbook();await w.xlsx.load(await E.normalizeXlsx(bytes));if(token!==epoch)return;workbook=w;report=E.analyzeWorkbook(w);candidates=report.candidates;$('excel-sheet').innerHTML=w.worksheets.map(s=>'<option value="'+s.id+'">'+escapeHTML(s.name)+'</option>').join('');$('excel-sheet').onchange();render();$('excel-review').hidden=false;$('excel-status').textContent=candidates.length?'自动识别完成，请查看汇总与集中校对项。':'尚未识别课程，请展开高级编辑或整理为日期列表。';dialog.scrollTop=0;}catch(e){if(token!==epoch)return;fail(e.message);$('excel-status').textContent='未导入，原课表已保留。';}};
})();
